=== FILE: prefix_validator.py ===
"""Topic path subscription matcher."""
def is_topic_subscribed(subscribed_pattern: str, event_topic: str) -> bool:
    # If the event topic is exactly the subscribed pattern, it matches.
    if event_topic == subscribed_pattern:
        return True

    # If the event topic starts with the subscribed pattern,
    # we need to ensure that the match is at a topic segment boundary.
    # For example, "orders" should match "orders::created" but not "orders_admin::created".
    if event_topic.startswith(subscribed_pattern):
        # Check if the character immediately following the subscribed pattern
        # in the event topic is the start of a segment separator (::).
        # This implies that the subscribed pattern matches a full segment or the root.
        idx = len(subscribed_pattern)
        if idx < len(event_topic) and event_topic[idx:idx+2] == "::":
            return True
    return False

def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()

def is_wildcard_subscription(pattern: str) -> bool:
    return pattern.strip() in ("*", "**")
